use std::collections::HashMap;
use std::collections::LinkedList;

pub struct LruCache<K, V> {
    capacity: usize,
    // key -> node in the doubly-linked list (MRU at back, LRU at front)
    map: HashMap<K, LinkedListNode>,
    // doubly-linked list of nodes, in access order
    list: LinkedList<LinkedListNode>,
}

// Wrapper so we can store nodes by reference in the HashMap
// while keeping them owned by the LinkedList.
struct LinkedListNode {
    key: K,
    value: V,
    prev: *mut LinkedListNode,
    next: *mut LinkedListNode,
}

impl<K, V> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache {
            capacity,
            map: HashMap::new(),
            list: LinkedList::new(),
        }
    }

